import 'package:web/web.dart' as web;

// Sons embutidos (WAV em base64): não dependem de assets nem de pacotes de áudio.
const String _clickUri = 'data:audio/wav;base64,';
const String _successUri = 'data:audio/wav;base64,';
const String _errorUri = 'data:audio/wav;base64,';

/// Toca efeitos sonoros curtos na web usando o elemento <audio> do navegador.
class SoundService {
  final Map<String, web.HTMLAudioElement> _cache = {};

  void _play(String uri) {
    try {
      final audio = _cache.putIfAbsent(uri, () {
        final el = web.document.createElement('audio') as web.HTMLAudioElement;
        el.src = uri;
        el.volume = 0.6;
        return el;
      });
      audio.currentTime = 0;
      audio.play();
    } catch (_) {
      // Som é opcional: nunca deve quebrar o jogo.
    }
  }

  void playClick() => _play(_clickUri);
  void playSuccess() => _play(_successUri);
  void playError() => _play(_errorUri);

  void dispose() {
    _cache.clear();
  }
}
